import {ElementDef, Parser} from "htmlparserts/parser";
import {PeekingTokenizer} from "htmlparserts/PeekingTokenizer";
import {getText, HtmlTokenizer, isToken, Token} from "htmlparserts/HtmlTokenizer";
import {Tokenizer} from "htmlparserts/tokenizer";

export type PlaceHolderType = "content" | "attribute";
export interface PlaceHolder {
    placeHolderId: string;
    pos: number;
    length: number;
    elementId: string; //todo: bundle per element. ElementFiller contains a list of placeholders.
    type: PlaceHolderType;
    nodeIndex: number;  //todo: make this depend on type.
    attributeName: string; //todo: make this depend on type.
    textParts: string[]; //place placeholder text in between each array item.
    placeHolderParts: PlaceHolderParts;
}

export function createPlaceHolders(code: string) {
    let parser = new Parser(new PeekingTokenizer(new HtmlTokenizer(code)));
    let nodes = parser.parse();
    let placeholders: PlaceHolder[] = [];
    //recursively generate placeholders.
    for(let i = 0; i < nodes.length; i++) {
        let element = nodes[i];
        if (typeof element == "string") {
            throw new Error("Top level text can't have placeholders.");
        } else
            addPlaceHolder(element, placeholders);

    }
    // console.log(JSON.stringify(placeholders, null, 2));
    return placeholders;
}

function addPlaceHolder(element: ElementDef, placeHolders: PlaceHolder[]): void {
    let attDef = element.attributes.get("id");
    let id = attDef == null ? null : (attDef.value == null ? null : getText(attDef.value));
    // generate attribute placeholders.
    for (let [attributeName, attrValue] of element.attributes) {
        if (attrValue.value == null)
            continue;
        let attrValueText = getText(attrValue.value);
        if (attrValueText.includes("{")) {
            if (attDef == null)
                throw new Error("Element must have an id to use placeholders.");
            placeHolders.push(
                ...createTextPlaceholders(
                    attrValue.value,
                    "attribute",
                    id??"--no id--",
                    -1,
                    attributeName,
                )
            );
        }
    }
    // generate content placeholders.
    for (let [i, node] of element.nodes.entries()) {
        if (isToken(node)) {
            placeHolders.push(
                ...createTextPlaceholders(
                    node,
                    "content",
                    id??"--no id--",
                    i,
                    "",
                )
            );
        } else {
            addPlaceHolder(node, placeHolders);
        }
    }
}

function createTextPlaceholders(token: Token, type: PlaceHolderType, elementId: string | undefined, nodeIndex: number, attributeName: string): PlaceHolder[] {
    let text = token.cursor.getText(token.pos, token.length);
    if (!text.includes("{")) {
        return [];
    }
    if (elementId == null)
        throw new Error("Element must have an id to use placeholders.");

    let placeholders: PlaceHolder[] = [];
    let rx = /{(\S+)}/gm;
    let match: RegExpExecArray | null;
    while((match = rx.exec(text)) != null) {
        let placeHolder = match[1];
        let placeHolderParts = parsePlaceHolder(placeHolder);
        placeholders.push({
            placeHolderId: placeHolderParts.placeHolderId,
            pos: token.pos + match.index,
            length: match[0].length,
            elementId,
            type,
            nodeIndex,
            attributeName,
            textParts: text.split(match[0]),
            placeHolderParts: placeHolderParts
        });
    }

    return placeholders;
}

interface PlaceHolderParts {
    placeHolderId: string;
    trueValue: string | null;
    falseValue: string | null;
    defaultValue: string | null;
}
function parsePlaceHolder(placeHolder: string): PlaceHolderParts {
    let defaultSplit = placeHolder.split("=");
    let defaultValue = defaultSplit.length > 1 ? defaultSplit[1] : null;
    let parts = defaultSplit[0].split("?");
    if (parts.length == 1) {
        return {placeHolderId: parts[0], trueValue: null, falseValue: null, defaultValue};
    }
    let parts2 = parts[1].split(":");
    if (parts2.length == 1) {
        return {placeHolderId: parts[0], trueValue: parts2[0], falseValue: null, defaultValue};
    }
    return {placeHolderId: parts[0], trueValue: parts2[0], falseValue: parts2[1], defaultValue};
}
